      let text;
      try { text = git(f.directory, ['show', key]); } catch { throw Object.assign(new Error('Not Found'), {status: 404}); }
      return {data: {encoding: 'base64', content: Buffer.from(text).toString('base64'), size: Buffer.byteLength(text)}};
